import{_ as a,o as i,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const m=JSON.parse('{"title":"教程引导与新手流程导航","description":"","frontmatter":{},"headers":[],"relativePath":"项目设计/教程引导与新手流程导航.md","filePath":"项目设计/教程引导与新手流程导航.md","lastUpdated":1777893104000}'),o={name:"项目设计/教程引导与新手流程导航.md"};function r(c,l,h,t,n,s){return i(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="教程引导与新手流程导航" tabindex="-1">教程引导与新手流程导航 <a class="header-anchor" href="#教程引导与新手流程导航" aria-label="Permalink to “教程引导与新手流程导航”">​</a></h1><p>一句话摘要：这是一份面向新手引导、教学流程和前期体验设计的专题入口，重点关注提示节奏、步骤状态、UI 引导和任务驱动之间的配合。</p><ul><li>适合对象：正在做新手教程、引导任务、前期教学流程的制作者</li><li>当前状态：已整理</li><li>可信度：<code>[高可信推断]</code></li><li>关联文档：<code>docs/脚本系统/专题研究/创游世界任务与事件系统设计入门.md</code>、<code>docs/脚本系统/专题研究/创游世界交互系统设计入门.md</code>、<code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li></ul><h2 id="这页适合解决什么问题" tabindex="-1">这页适合解决什么问题 <a class="header-anchor" href="#这页适合解决什么问题" aria-label="Permalink to “这页适合解决什么问题”">​</a></h2><ul><li>新手引导为什么容易写成一堆硬编码</li><li>点击提示、任务步骤、对话、UI 高亮应该怎么配合</li><li>玩家跳步骤、退出页面、重复触发时怎么处理</li><li>引导到底应该放任务系统里，还是单独做状态机</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to “推荐阅读顺序”">​</a></h2><ol><li><code>docs/脚本系统/专题研究/创游世界任务与事件系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界交互系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界广播驱动项目结构实战.md</code></li></ol><h2 id="教程引导最重要的设计观念" tabindex="-1">教程引导最重要的设计观念 <a class="header-anchor" href="#教程引导最重要的设计观念" aria-label="Permalink to “教程引导最重要的设计观念”">​</a></h2><ul><li><code>[已确认]</code> 引导本质上是一组“条件 → 提示 → 完成 → 下一步”的流程控制。</li><li><code>[已确认]</code> 引导信息和引导状态应尽量分开。</li><li><code>[已确认]</code> UI 高亮、文字提示、任务目标和交互检测不应混成一个脚本大杂烩。</li><li><code>[高可信推断]</code> 如果项目后面内容很多，教程系统最好尽早做成可配置、可跳过、可恢复的结构。</li></ul><h2 id="推荐拆分方式" tabindex="-1">推荐拆分方式 <a class="header-anchor" href="#推荐拆分方式" aria-label="Permalink to “推荐拆分方式”">​</a></h2><h3 id="引导状态层" tabindex="-1">引导状态层 <a class="header-anchor" href="#引导状态层" aria-label="Permalink to “引导状态层”">​</a></h3><p>负责：</p><ul><li>当前进行到第几步</li><li>该步是否完成</li><li>是否允许跳过 / 回退 / 重新触发</li></ul><h3 id="条件检测层" tabindex="-1">条件检测层 <a class="header-anchor" href="#条件检测层" aria-label="Permalink to “条件检测层”">​</a></h3><p>负责：</p><ul><li>玩家是否完成指定点击</li><li>是否进入指定地图</li><li>是否获得指定物品</li><li>是否打开指定 UI</li></ul><h3 id="提示展示层" tabindex="-1">提示展示层 <a class="header-anchor" href="#提示展示层" aria-label="Permalink to “提示展示层”">​</a></h3><p>负责：</p><ul><li>文本提示</li><li>箭头 / 高亮 / 遮罩</li><li>对话框 / 引导弹窗</li></ul><h3 id="推进控制层" tabindex="-1">推进控制层 <a class="header-anchor" href="#推进控制层" aria-label="Permalink to “推进控制层”">​</a></h3><p>负责：</p><ul><li>完成当前步骤</li><li>切换到下一步骤</li><li>处理中断、退出、重进</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><ul><li>误区 1：把所有教程逻辑硬写在一个页面脚本里。 <ul><li>后果：流程稍一复杂就难改。</li></ul></li><li>误区 2：只做“显示提示”，不记录步骤状态。 <ul><li>后果：玩家重复触发或中断后很容易乱套。</li></ul></li><li>误区 3：教程和主任务互相打架。 <ul><li>后果：流程源头不清，条件冲突频繁出现。</li></ul></li></ul><h2 id="当前仍建议继续补强的部分" tabindex="-1">当前仍建议继续补强的部分 <a class="header-anchor" href="#当前仍建议继续补强的部分" aria-label="Permalink to “当前仍建议继续补强的部分”">​</a></h2><ul><li>新手流程状态机示例</li><li>可跳过教程设计建议</li><li>教程引导与任务系统的边界规则</li><li>UI 高亮与遮罩组件化方案</li></ul><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to “关联阅读”">​</a></h2><ul><li><code>docs/项目设计/项目设计导航.md</code></li><li><code>docs/项目设计/系统设计专题导航.md</code></li><li><code>docs/核心研究/UI与交互研究导航.md</code></li></ul>',28)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
